import { createHash } from 'node:crypto'
import { mkdir, rm, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { clipboard } from 'electron'

const MAX_IMAGE_BYTES = 5 * 1024 * 1024
// Formats that password managers / the OS set to mark a copy as secret or transient.
const CONCEALED = [
  'org.nspasteboard.ConcealedType',
  'org.nspasteboard.TransientType',
  'org.nspasteboard.AutoGeneratedType',
  'ExcludeClipboardContentFromMonitorProcessing',
  'x-kde-passwordManagerHint',
]

export type ClipMessage =
  | { type: 'clip-text'; text: string; concealed: boolean }
  | { type: 'clip-image'; hash: string; bytes: number; concealed: boolean }

/** Polls the system clipboard (Electron has no change event). Nothing leaves this machine. */
export function watchClipboard(
  imagesDir: string,
  send: (m: ClipMessage) => void,
  isPaused: () => boolean,
  intervalMs = 600,
): () => void {
  let lastText: string | undefined
  let lastImage = ''
  let busy = false
  const tick = async () => {
    const items = await clipboard.read()
    const types = items.flatMap((i) => i.types)
    const concealed = types.some((f) => CONCEALED.some((c) => f.toLowerCase() === c.toLowerCase()))
    const text = await clipboard.readText()
    if (lastText === undefined) {
      lastText = text // don't record whatever was on the clipboard before Beacon started
      return
    }
    if (text) {
      if (text !== lastText) {
        lastText = text
        send({ type: 'clip-text', text, concealed })
      }
      return
    }
    lastText = ''
    const imgItem = items.find((i) => i.types.includes('image/png'))
    if (!imgItem) return
    const png = Buffer.from(await (await imgItem.getType('image/png')).arrayBuffer())
    if (!png.length) return
    const hash = createHash('sha256').update(png).digest('hex').slice(0, 16)
    if (hash === lastImage) return
    lastImage = hash
    if (png.length > MAX_IMAGE_BYTES) return
    if (!concealed) {
      await mkdir(imagesDir, { recursive: true })
      await writeFile(join(imagesDir, `${hash}.png`), png)
    }
    send({ type: 'clip-image', hash, bytes: png.length, concealed })
  }
  const timer = setInterval(() => {
    if (busy || isPaused()) return
    busy = true
    tick()
      .catch(() => undefined /* clipboard busy; try next tick */)
      .finally(() => (busy = false))
  }, intervalMs)
  return () => clearInterval(timer)
}

export async function deleteImages(imagesDir: string, hashes: string[]): Promise<void> {
  for (const h of hashes)
    if (/^[0-9a-f]{16}$/.test(h)) await rm(join(imagesDir, `${h}.png`), { force: true })
}
